        if (r.length==0){ bs[i]=Bound{Key(0),false}; be[i]=Bound{Key(0),true}; }
        else { Key size=Key(1)<<(128-r.length); bs[i]=Bound{r.start,false}; Key e=r.start+size; be[i]=(e<r.start)?Bound{Key(0),true}:Bound{e,false}; }
        std::cout << "route " << i << " start=" << hexkey(bs[i].v) << " top=" << bs[i].top << " end=" << hexkey(be[i].v) << " top=" << be[i].top << "\n";
    }
    std::vector<Bound> pts;
    pts.push_back(Bound{Key(0),false}); pts.push_back(Bound{Key(0),true});
    for (std::size_t i=0;i<n;++i){pts.push_back(bs[i]);pts.push_back(be[i]);}
    std::sort(pts.begin(),pts.end(),cmpBound);
    for (auto&p:pts) std::cout << "pt " << hexkey(p.v) << " top=" << p.top << "\n";
}
